const default_allocator = bun.default_allocator;
const js_printer = bun.js_printer;
const logger = bun.logger;
const strings = bun.strings;
const BabyList = bun.collections.BabyList;
const Indentation = js_printer.Options.Indentation;
const js_ast = bun.ast;
const E = js_ast.E;
const ExprNodeList = js_ast.ExprNodeList;
const G = js_ast.G;
const Stmt = js_ast.Stmt;
const js_lexer = bun.js_lexer;
const Token = js_lexer.T;

pub fn newExpr(t: anytype, loc: logger.Loc) Expr {
        const Type = @TypeOf(t);
        if (comptime (@typeInfo(Type) == .pointer)) {
            _ = @compileError("Unexpected pointer");
        }
        if (comptime Environment.allow_assert) {
            if (comptime (Type == E.Object)) {
                for (t.properties.slice()) |prop| {
                    _ = &prop;
                    _ = bun.assert((prop.initializer == null));
                    _ = bun.assert((prop.key != null));
                    _ = bun.assert(((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value) != null));
                }
            }
        }
        return Expr.init(Type, t, loc);
}

pub fn parseJSONMaybeTrailingComma(p: anytype, comptime opts: js_lexer.JSONOptions, closer: js_lexer.T) !bool {
        const comma_range = p.lexer.range();
        _ = try p.lexer.expect(.t_comma);
        if ((p.lexer.token == closer)) {
            if ((!opts.allow_trailing_commas)) {
                _ = ((p.log.addRangeError(p.source(), comma_range, "JSON does not support trailing commas")) catch unreachable);
            }
            return false;
        }
        return true;
}

pub fn parseJSONExpr(p: anytype, comptime opts: js_lexer.JSONOptions, comptime maybe_auto_quote: bool, comptime force_utf8: bool) !Expr {
        if ((!p.stack_check.isSafeToRecurse())) {
            _ = try bun.throwStackOverflow();
        }
        const loc = p.lexer.loc();
        switch (p.lexer.token) {
.t_false => {
_ = try p.lexer.next();
        return newExpr(E.Boolean{ .value = false }, loc);
},
.t_true => {
_ = try p.lexer.next();
        return newExpr(E.Boolean{ .value = true }, loc);
},
.t_null => {
_ = try p.lexer.next();
        return newExpr(std.mem.zeroes(E.Null), loc);
},
.t_string_literal => {
var str: E.String = try p.lexer.toEString();
        _ = &str;
        if (force_utf8) {
            _ = ((str.toUTF8(p.allocator)) catch unreachable);
        }
        _ = try p.lexer.next();
        return newExpr(str, loc);
},
.t_numeric_literal => {
const value = p.lexer.number;
        _ = try p.lexer.next();
        return newExpr(E.Number{ .value = value }, loc);
},
.t_minus => {
_ = try p.lexer.next();
        const value = p.lexer.number;
        _ = try p.lexer.expect(.t_numeric_literal);
        return newExpr(E.Number{ .value = (0 - value) }, loc);
},
.t_open_bracket => {
_ = try p.lexer.next();
        var is_single_line = (!p.lexer.has_newline_before);
        _ = &is_single_line;
        var exprs = std.array_list.Managed(Expr).init(p.list_allocator);
        _ = &exprs;
        errdefer {
        _ = exprs.deinit();
        }
        while ((p.lexer.token != .t_close_bracket)) {
            if ((exprs.items.len > 0)) {
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
                if ((!try parseJSONMaybeTrailingComma(p, opts, .t_close_bracket))) {
                    break;
                }
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
            }
            _ = ((exprs.append(try parseJSONExpr(p, opts, false, force_utf8))) catch unreachable);
        }
        if (p.lexer.has_newline_before) {
            is_single_line = false;
        }
        _ = try p.lexer.expect(.t_close_bracket);
        return newExpr(E.Array{ .items = ExprNodeList.moveFromList((&exprs)), .is_single_line = is_single_line, .was_originally_macro = opts.was_originally_macro }, loc);
},
.t_open_brace => {
_ = try p.lexer.next();
        var is_single_line = (!p.lexer.has_newline_before);
        _ = &is_single_line;
        var properties = std.array_list.Managed(G.Property).init(p.list_allocator);
        _ = &properties;
        errdefer {
        _ = properties.deinit();
        }
        const DuplicateNodeType = (if (opts.json_warn_duplicate_keys) *HashMapPool.LinkedList.Node else void);
        const HashMapType = (if (opts.json_warn_duplicate_keys) HashMapPool.HashMap else void);
        var duplicates_node: DuplicateNodeType = (if (opts.json_warn_duplicate_keys) HashMapPool.get(p.allocator) else undefined);
        _ = &duplicates_node;
        var duplicates: HashMapType = (if (opts.json_warn_duplicate_keys) duplicates_node.data else undefined);
        _ = &duplicates;
        defer {
        {
            if (opts.json_warn_duplicate_keys) {
                duplicates_node.data = duplicates;
                const release_fn = HashMapPool.release;
                _ = release_fn(duplicates_node);
            }
        }
        }
        while ((p.lexer.token != .t_close_brace)) {
            if ((properties.items.len > 0)) {
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
                if ((!try parseJSONMaybeTrailingComma(p, opts, .t_close_brace))) {
                    break;
                }
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
            }
            const str = (if (force_utf8) try p.lexer.toUTF8EString() else try p.lexer.toEString());
            const key_range = p.lexer.range();
            const key = newExpr(str, key_range.loc);
            _ = try p.lexer.expect(.t_string_literal);
            if (opts.json_warn_duplicate_keys) {
                const hash_key = str.hash();
                const duplicate_get_or_put = ((duplicates.getOrPut(hash_key)) catch unreachable);
                duplicate_get_or_put.key_ptr.* = hash_key;
                if (duplicate_get_or_put.found_existing) {
                    _ = ((p.log.addRangeWarningFmt(p.source(), key_range, p.allocator, "Duplicate key \"{s}\" in object literal", .{ try str.string(p.allocator) })) catch unreachable);
                }
            }
            _ = try p.lexer.expect(.t_colon);
            const value = try parseJSONExpr(p, opts, false, force_utf8);
            _ = ((properties.append(G.Property{ .key = key, .value = value, .kind = js_ast.G.Property.Kind.normal, .initializer = null })) catch unreachable);
        }
        if (p.lexer.has_newline_before) {
            is_single_line = false;
        }
        _ = try p.lexer.expect(.t_close_brace);
        return newExpr(E.Object{ .properties = G.Property.List.moveFromList((&properties)), .is_single_line = is_single_line, .was_originally_macro = opts.was_originally_macro }, loc);
},
else => {
if (maybe_auto_quote) {
            p.lexer = try @TypeOf(p.lexer).initJSON(p.log, p.source(), p.allocator);
            _ = try p.lexer.parseStringLiteral(0);
            return parseJSONExpr(p, opts, false, force_utf8);
        }
        _ = try p.lexer.unexpected();
        return error.ParserError;
},
}
}

pub fn JSONLikeParser(comptime opts: js_lexer.JSONOptions) type {
        return JSONLikeParser_(opts.is_json, opts.allow_comments, opts.allow_trailing_commas, opts.ignore_leading_escape_sequences, opts.ignore_trailing_escape_sequences, opts.json_warn_duplicate_keys, opts.was_originally_macro, opts.guess_indentation);
}

pub fn JSONLikeParser_(comptime opts_is_json: bool, comptime opts_allow_comments: bool, comptime opts_allow_trailing_commas: bool, comptime opts_ignore_leading_escape_sequences: bool, comptime opts_ignore_trailing_escape_sequences: bool, comptime opts_json_warn_duplicate_keys: bool, comptime opts_was_originally_macro: bool, comptime opts_guess_indentation: bool) type {
        const opts = js_lexer.JSONOptions{ .is_json = opts_is_json, .allow_comments = opts_allow_comments, .allow_trailing_commas = opts_allow_trailing_commas, .ignore_leading_escape_sequences = opts_ignore_leading_escape_sequences, .ignore_trailing_escape_sequences = opts_ignore_trailing_escape_sequences, .json_warn_duplicate_keys = opts_json_warn_duplicate_keys, .was_originally_macro = opts_was_originally_macro, .guess_indentation = opts_guess_indentation };
        return struct {
    lexer: Lexer,
    log: *logger.Log,
    allocator: std.mem.Allocator,
    list_allocator: std.mem.Allocator,
    stack_check: bun.StackCheck,

pub fn init(allocator: std.mem.Allocator, source_: *const logger.Source, log: *logger.Log) !Parser {
            return initWithListAllocator(allocator, allocator, source_, log);
    }

pub fn initWithListAllocator(allocator: std.mem.Allocator, list_allocator: std.mem.Allocator, source_: *const logger.Source, log: *logger.Log) !Parser {
            _ = Expr.Data.Store.assert();
            _ = Stmt.Data.Store.assert();
            return Parser{ .lexer = try Lexer.init(log, source_, allocator), .allocator = allocator, .log = log, .list_allocator = list_allocator, .stack_check = bun.StackCheck.init() };
    }

pub inline fn source(p: *const Parser) *const logger.Source {
            return (&p.lexer.source);
    }

pub fn parseExpr(p: *Parser, comptime maybe_auto_quote: bool, comptime force_utf8: bool) anyerror!Expr {
            return parseJSONExpr(p, opts, maybe_auto_quote, force_utf8);
    }

pub fn parseMaybeTrailingComma(p: *Parser, closer: js_lexer.T) !bool {
            return parseJSONMaybeTrailingComma(p, opts, closer);
    }
    const Lexer = js_lexer.NewLexer((if (LEXER_DEBUGGER_WORKAROUND) js_lexer.JSONOptions{  } else opts));
    const Parser = @This();
};
}

pub fn toAST(allocator: std.mem.Allocator, comptime Type: type, value: Type) !js_ast.Expr {
        const type_info: std.builtin.Type = @typeInfo(Type);
        switch (type_info) {
.bool => {
return Expr{ .data = .{ .e_boolean = .{ .value = value } }, .loc = logger.Loc{  } };
},
.int => {
const f: f64 = @floatFromInt(value);
        return Expr{ .data = .{ .e_number = .{ .value = f } }, .loc = logger.Loc{  } };
},
.float => {
const f: f64 = @floatCast(value);
        return Expr{ .data = .{ .e_number = .{ .value = f } }, .loc = logger.Loc{  } };
},
.pointer => |ptr_info| {
switch (ptr_info.size) {
.one => {
switch (@typeInfo(ptr_info.child)) {
.array => {
const Slice = []const std.meta.Elem(ptr_info.child);
        return try toAST(allocator, Slice, value.*);
},
else => {
return try toAST(allocator, @TypeOf(value.*), value.*);
},
}
},
.slice => {
if ((ptr_info.child == u8)) {
            return Expr.init(js_ast.E.String, js_ast.E.String.init(value), logger.Loc.Empty);
        }
        const exprs = try allocator.alloc(Expr, value.len);
        for (exprs, 0..) |*ex, i| {
            _ = &ex;
            _ = &i;
            ex.* = try toAST(allocator, @TypeOf(value[@as(usize, @intCast(i))]), value[@as(usize, @intCast(i))]);
        }
        return Expr.init(js_ast.E.Array, js_ast.E.Array{ .items = exprs }, logger.Loc.Empty);
},
else => {
_ = @compileError(std.fmt.comptimePrint("Unable to stringify type '{s}'", .{ @typeName(Type) }));
},
}
},
.array => |Array| {
if ((Array.child == u8)) {
            return Expr.init(js_ast.E.String, js_ast.E.String.init(value), logger.Loc.Empty);
        }
        const exprs = try allocator.alloc(Expr, value.len);
        for (exprs, 0..) |*ex, i| {
            _ = &ex;
            _ = &i;
            ex.* = try toAST(allocator, @TypeOf(value[@as(usize, @intCast(i))]), value[@as(usize, @intCast(i))]);
        }
        return Expr.init(js_ast.E.Array, js_ast.E.Array{ .items = exprs }, logger.Loc.Empty);
},
.@"struct" => |Struct| {
const fields: []const std.builtin.Type.StructField = Struct.fields;
        var properties = try BabyList(js_ast.G.Property).initCapacity(allocator, fields.len);
        _ = &properties;
        inline for (fields) |field| {
            _ = &field;
            _ = properties.appendAssumeCapacity(G.Property{ .key = Expr.init(E.String, E.String{ .data = (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name) }, logger.Loc.Empty), .value = try toAST(allocator, field.type, @field(value, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name))) });
        }
        return Expr.init(js_ast.E.Object, js_ast.E.Object{ .properties = properties, .is_single_line = (properties.len <= 1) }, logger.Loc.Empty);
},
.null => {
return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } };
},
.optional => {
if (value) |_value| {
            _ = &_value;
            return try toAST(allocator, @TypeOf(_value), _value);
        } else {
            return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } };
        }
},
.@"enum" => {
_ = (blk_catch_7: { break :blk_catch_7 ((std.meta.intToEnum(Type, @intFromEnum(value))) catch |__ce_7| { _ = &__ce_7; return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } }; }); });
        return toAST(allocator, string, @as([]const u8, @tagName(value)));
},
.error_set => {
return try toAST(allocator, string, bun.asByteSlice(@errorName(value)));
},
.@"union" => |Union| {
const info = Union;
        if (info.tag_type) |UnionTagType| {
            _ = &UnionTagType;
            inline for (info.fields) |u_field| {
                _ = &u_field;
                if ((value == @field(UnionTagType, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)))) {
                    const StructType = @Type(.{ .Struct = .{ .layout = .Auto, .decls = (&.{}), .is_tuple = false, .fields = (&.{ .{ .name = (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name), .type = @TypeOf(@field(value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name))), .is_comptime = false, .default_value_ptr = undefined, .alignment = @alignOf(@TypeOf(@field(value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)))) } }) } });
                    var struct_value: StructType = undefined;
                    _ = &struct_value;
                    @field(struct_value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)) = value;
                    return try toAST(allocator, StructType, struct_value);
                }
            }
        } else {
            _ = @compileError(std.fmt.comptimePrint("Unable to stringify untagged union '{s}'", .{ @typeName(Type) }));
        }
},
else => {
_ = @compileError(std.fmt.comptimePrint("Unsupported type: {s} - {s}", .{ @tagName(type_info), @typeName(Type) }));
},
}
}

pub fn parse(source: *const logger.Source, log: *logger.Log, allocator: std.mem.Allocator, comptime force_utf8: bool) !Expr {
        var parser = try JSONParser.init(allocator, source, log);
        _ = &parser;
        switch (source.contents.len) {
0 => {
return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
},
2 => {
if ((strings.eqlComptime(source.contents[0..1], "\"\"") or strings.eqlComptime(source.contents[0..1], "''"))) {
            return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_string_data };
        } else {
            if (strings.eqlComptime(source.contents[0..1], "{}")) {
                return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
            } else {
                if (strings.eqlComptime(source.contents[0..1], "[]")) {
                    return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_array_data };
                }
            }
        }
},
else => {

},
}
        return try parser.parseExpr(false, force_utf8);
}

pub fn parsePackageJSONUTF8(source: *const logger.Source, log: *logger.Log, allocator: std.mem.Allocator) !Expr {
        const len = source.contents.len;
        switch (len) {
0 => {
return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
},
2 => {
if ((strings.eqlComptime(source.contents[0..1], "\"\"") or strings.eqlComptime(source.contents[0..1], "''"))) {
            return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_string_data };
        } else {
            if (strings.eqlComptime(source.contents[0..1], "{}")) {
                return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
            } else {
                if (strings.eqlComptime(source.contents[0..1], "[]")) {
                    return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_array_data };
                }
            }
        }
},
else => {

},
}
        var parser = try JSONLikeParser(.{ .is_json = true, .allow_comments = true, .allow_trailing_commas = true }).init(allocator, source, log);
        _ = &parser;
        _ = bun.assert((parser.source().contents.len > 0));
        return try parser.parseExpr(false, true);
}

